const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));document.querySelector('.rsvp-form').addEventListener('submit',e=>{e.preventDefault();e.currentTarget.querySelector('.form-note').textContent='You are on the list. We will be in touch soon.'});
